{"type":"item.completed","item":{"id":"item_0","type":"agent_message","text":"{\"items\":[{\"id\":\"cap-v2-sequence_algorithms-python-repair-01\",\"test_code\":\"import unittest\\n\\nfrom solution import prioritize_tasks\\n\\n\\nclass PrioritizeTasksTests(unittest.TestCase):\\n    def test_stable_partition_with_uneven_categories(self):\\n        tasks = [\\n            {\\\"id\\\": 1, \\\"category\\\": \\\"slow\\\"},\\n            {\\\"id\\\": 2, \\\"category\\\": \\\"fast\\\"},\\n            {\\\"id\\\": 3, \\\"category\\\": \\\"slow\\\"},\\n            {\\\"id\\\": 4, \\\"category\\\": \\\"fast\\\"},\\n            {\\\"id\\\": 5, \\\"category\\\": \\\"other\\\"},\\n        ]\\n        result = prioritize_tasks(tasks, [\\\"slow\\\"])\\n        self.assertEqual([task[\\\"id\\\"] for task in result], [2, 4, 5, 1, 3])\\n        self.assertIs(result[0], tasks[1])\\n        self.assertIs(result[1], tasks[3])\\n        self.assertIs(result[2], tasks[4])\\n        self.assertIs(result[3], tasks[0])\\n        self.assertIs(result[4], tasks[2])\\n\\n    def test_empty_inputs_and_boundary_partitions(self):\\n        self.assertEqual(prioritize_tasks([], []), [])\\n\\n        tasks = [{\\\"category\\\": \\\"a\\\"}, {\\\"category\\\": \\\"b\\\"}]\\n        all_ready = prioritize_tasks(tasks, [])\\n        all_delayed = prioritize_tasks(tasks, [\\\"a\\\", \\\"b\\\"])\\n        self.assertEqual(all_ready, tasks)\\n        self.assertEqual(all_delayed, tasks)\\n        self.assertIsNot(all_ready, tasks)\\n        self.assertIsNot(all_delayed, tasks)\\n\\n    def test_duplicate_delayed_categories_are_harmless(self):\\n        tasks = [\\n            {\\\"id\\\": \\\"a\\\", \\\"category\\\": 1},\\n            {\\\"id\\\": \\\"b\\\", \\\"category\\\": 2},\\n            {\\\"id\\\": \\\"c\\\", \\\"category\\\": 1},\\n        ]\\n        result = prioritize_tasks(tuple(tasks), [1, 1, 1])\\n        self.assertEqual([task[\\\"id\\\"] for task in result], [\\\"b\\\", \\\"a\\\", \\\"c\\\"])\\n\\n    def test_does_not_mutate_input_or_copy_task_objects(self):\\n        nested = {\\\"values\\\": []}\\n        tasks = [\\n            {\\\"id\\\": 1, \\\"category\\\": \\\"delayed\\\", \\\"nested\\\": nested},\\n            {\\\"id\\\": 2, \\\"category\\\": \\\"ready\\\"},\\n        ]\\n        original_order = list(tasks)\\n        result = prioritize_tasks(tasks, {\\\"delayed\\\"})\\n\\n        self.assertEqual(tasks, original_order)\\n        self.assertIs(tasks[0], original_order[0])\\n        self.assertIs(result[1], tasks[0])\\n        self.assertIs(result[1][\\\"nested\\\"], nested)\\n\\n    def test_missing_required_category_raises_without_reordering_input(self):\\n        tasks = [{\\\"id\\\": 1, \\\"category\\\": \\\"ready\\\"}, {\\\"id\\\": 2}]\\n        original = list(tasks)\\n        with self.assertRaises(KeyError):\\n            prioritize_tasks(tasks, {\\\"slow\\\"})\\n        self.assertEqual(tasks, original)\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    unittest.main()\\n\"},{\"id\":\"cap-v2-sequence_algorithms-python-repair-02\",\"test_code\":\"import unittest\\n\\nfrom solution import weave_queues\\n\\n\\nclass WeaveQueuesTests(unittest.TestCase):\\n    def test_round_robin_order_is_left_to_right_and_stable(self):\\n        queues = [[\\\"a1\\\", \\\"a2\\\", \\\"a3\\\"], [\\\"b1\\\", \\\"b2\\\"], [\\\"c1\\\", \\\"c2\\\", \\\"c3\\\", \\\"c4\\\"]]\\n        self.assertEqual(\\n            weave_queues(queues),\\n            [\\\"a1\\\", \\\"b1\\\", \\\"c1\\\", \\\"a2\\\", \\\"b2\\\", \\\"c2\\\", \\\"a3\\\", \\\"c3\\\", \\\"c4\\\"],\\n        )\\n\\n    def test_empty_outer_and_empty_inner_queues(self):\\n        self.assertEqual(weave_queues([]), [])\\n        self.assertEqual(weave_queues([[], (), []]), [])\\n        self.assertEqual(weave_queues([[], [1, 2], (), [3]]), [1, 3, 2])\\n\\n    def test_single_queue_and_one_item_queues(self):\\n        self.assertEqual(weave_queues([(1, 2, 3)]), [1, 2, 3])\\n        self.assertEqual(weave_queues([[1], [2], [3]]), [1, 2, 3])\\n\\n    def test_returns_original_objects(self):\\n        a1, a2, b1, b2 = object(), object(), object(), object()\\n        result = weave_queues([[a1, a2], (b1, b2)])\\n        expected = [a1, b1, a2, b2]\\n        self.assertEqual(len(result), len(expected))\\n        for actual, original in zip(result, expected):\\n            self.assertIs(actual, original)\\n\\n    def test_does_not_mutate_outer_or_inner_sequences(self):\\n        first = [{\\\"n\\\": 1}, {\\\"n\\\": 2}]\\n        second = [{\\\"n\\\": 3}]\\n        queues = [first, second]\\n        outer_before = list(queues)\\n        first_before = list(first)\\n        second_before = list(second)\\n\\n        result = weave_queues(queues)\\n\\n        self.assertEqual(queues, outer_before)\\n        self.assertEqual(first, first_before)\\n        self.assertEqual(second, second_before)\\n        self.assertIs(result[0], first[0])\\n        self.assertIs(result[1], second[0])\\n        self.assertIs(result[2], first[1])\\n\\n    def test_non_sequence_inner_value_is_rejected(self):\\n        with self.assertRaises((TypeError, AttributeError)):\\n            weave_queues([[1], None])\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    unittest.main()\\n\"},{\"id\":\"cap-v2-stateful_workflows-python-generation-01\",\"test_code\":\"import unittest\\n\\nfrom solution import make_document_workflow\\n\\n\\nclass DocumentWorkflowTests(unittest.TestCase):\\n    def test_commit_and_rollback_lifecycle(self):\\n        workflow = make_document_workflow({\\\"title\\\": \\\"old\\\", \\\"count\\\": 1})\\n        self.assertEqual(workflow(\\\"view\\\"), {\\n            \\\"state\\\": \\\"idle\\\",\\n            \\\"document\\\": {\\\"title\\\": \\\"old\\\", \\\"count\\\": 1},\\n        })\\n\\n        workflow(\\\"begin\\\")\\n        workflow(\\\"put\\\", \\\"title\\\", \\\"new\\\")\\n        self.assertEqual(workflow(\\\"view\\\"), {\\n            \\\"state\\\": \\\"editing\\\",\\n      