{"type":"item.completed","item":{"id":"item_0","type":"agent_message","text":"{\"items\":[{\"id\":\"cap-v2-stateful_workflows-python-repair-02\",\"test_code\":\"import unittest\\n\\nfrom solution import ParcelWorkflow\\n\\n\\nclass ParcelWorkflowTests(unittest.TestCase):\\n    def test_initial_state(self):\\n        workflow = ParcelWorkflow()\\n        self.assertEqual(workflow.state, \\\"created\\\")\\n        self.assertEqual(workflow.transition_count, 0)\\n\\n    def test_complete_workflow_and_reopen(self):\\n        workflow = ParcelWorkflow()\\n        self.assertEqual(workflow.apply(\\\"c1\\\", \\\"pack\\\"), (\\\"packed\\\", 1))\\n        self.assertEqual(workflow.apply(\\\"c2\\\", \\\"ship\\\"), (\\\"shipped\\\", 2))\\n        self.assertEqual(workflow.apply(\\\"c3\\\", \\\"deliver\\\"), (\\\"delivered\\\", 3))\\n        self.assertEqual(workflow.apply(\\\"c4\\\", \\\"reopen\\\"), (\\\"shipped\\\", 4))\\n        self.assertEqual(workflow.state, \\\"shipped\\\")\\n        self.assertEqual(workflow.transition_count, 4)\\n\\n    def test_completed_command_is_idempotent_after_state_changes(self):\\n        workflow = ParcelWorkflow()\\n        original = workflow.apply(\\\"same\\\", \\\"pack\\\")\\n        workflow.apply(\\\"ship-command\\\", \\\"ship\\\")\\n        workflow.apply(\\\"deliver-command\\\", \\\"deliver\\\")\\n\\n        self.assertEqual(workflow.apply(\\\"same\\\", \\\"reopen\\\"), original)\\n        self.assertEqual(workflow.state, \\\"delivered\\\")\\n        self.assertEqual(workflow.transition_count, 3)\\n\\n    def test_immediate_retry_with_different_action_returns_recorded_result(self):\\n        workflow = ParcelWorkflow()\\n        self.assertEqual(workflow.apply(17, \\\"pack\\\"), (\\\"packed\\\", 1))\\n        self.assertEqual(workflow.apply(17, \\\"deliver\\\"), (\\\"packed\\\", 1))\\n        self.assertEqual(workflow.state, \\\"packed\\\")\\n        self.assertEqual(workflow.transition_count, 1)\\n\\n    def test_invalid_action_has_no_effect_and_id_is_not_recorded(self):\\n        workflow = ParcelWorkflow()\\n        with self.assertRaises(ValueError):\\n            workflow.apply(\\\"retryable\\\", \\\"ship\\\")\\n\\n        self.assertEqual(workflow.state, \\\"created\\\")\\n        self.assertEqual(workflow.transition_count, 0)\\n        self.assertEqual(workflow.apply(\\\"retryable\\\", \\\"pack\\\"), (\\\"packed\\\", 1))\\n\\n    def test_invalid_transition_after_success_does_not_change_state(self):\\n        workflow = ParcelWorkflow()\\n        workflow.apply(\\\"pack\\\", \\\"pack\\\")\\n\\n        with self.assertRaises(ValueError):\\n            workflow.apply(\\\"bad\\\", \\\"pack\\\")\\n\\n        self.assertEqual(workflow.state, \\\"packed\\\")\\n        self.assertEqual(workflow.transition_count, 1)\\n        self.assertEqual(workflow.apply(\\\"bad\\\", \\\"ship\\\"), (\\\"shipped\\\", 2))\\n\\n    def test_instances_have_independent_state_and_command_history(self):\\n        first = ParcelWorkflow()\\n        second = ParcelWorkflow()\\n        first.apply(\\\"shared-id\\\", \\\"pack\\\")\\n\\n        self.assertEqual(second.apply(\\\"shared-id\\\", \\\"pack\\\"), (\\\"packed\\\", 1))\\n        self.assertEqual(first.state, \\\"packed\\\")\\n        self.assertEqual(second.state, \\\"packed\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    unittest.main()\\n\"},{\"id\":\"cap-v2-string_and_unicode-python-generation-01\",\"test_code\":\"import unittest\\n\\nfrom solution import normalize_text_grid\\n\\n\\nclass NormalizeTextGridTests(unittest.TestCase):\\n    def test_empty_grid_and_empty_rows(self):\\n        self.assertEqual(normalize_text_grid([]), ())\\n        self.assertEqual(normalize_text_grid([[], []]), ((), ()))\\n\\n    def test_nfkc_and_whitespace_processing(self):\\n        grid = [\\n            [\\\"  Ｈｅｌｌｏ\\\\tworld\\\\n\\\", \\\"① + ²\\\", \\\"A\\\\u00a0\\\\u2003B\\\"],\\n            [\\\"\\\\u3000\\\", \\\"plain\\\", \\\"\\\"],\\n        ]\\n        self.assert